<?php
session_start(); if(!isset($_SESSION['admin'])){header('Location: ../index.php');exit;}
require_once __DIR__.'/../config/db.php'; require_once __DIR__.'/admincheck_role.php';
$msg='';$type='success';
if($_SERVER['REQUEST_METHOD']==='POST'){ems_verify_csrf();$action=$_POST['action']??'';
 try{
  if($action==='campaign'){$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');if($name===''||mb_strlen($name)>150||mb_strlen($desc)>5000)throw new RuntimeException('Enter a campaign name up to 150 characters and description up to 5,000 characters.');$s=$conn->prepare('INSERT INTO performance_campaigns(name,description) VALUES(?,?)');$s->bind_param('ss',$name,$desc);$s->execute();$msg='Campaign added successfully.';}
  elseif($action==='kpi'){$cid=(int)($_POST['campaign_id']??0);$name=trim($_POST['kpi_name']??'');$code=strtolower(preg_replace('/[^a-zA-Z0-9]+/','_',trim($_POST['kpi_code']??$name))??'');$code=trim($code,'_');$weight=(float)($_POST['weight']??0);if(!$cid||$name===''||$code===''||$weight<=0)throw new RuntimeException('Campaign, KPI name and positive weight are required.');$sum=$conn->prepare('SELECT COALESCE(SUM(weight),0) total FROM campaign_kpis WHERE campaign_id=?');$sum->bind_param('i',$cid);$sum->execute();$current=(float)$sum->get_result()->fetch_assoc()['total'];if($current+$weight>100.001)throw new RuntimeException('Total KPI weight cannot exceed 100%.');$s=$conn->prepare('INSERT INTO campaign_kpis(campaign_id,kpi_name,kpi_code,weight,display_order) VALUES(?,?,?,?,100)');$s->bind_param('issd',$cid,$name,$code,$weight);$s->execute();$msg='Campaign KPI added successfully.';}
  elseif($action==='assign'){$cid=(int)($_POST['campaign_id']??0);$eid=(int)($_POST['employee_id']??0);$from=$_POST['assigned_from']??date('Y-m-d');if(!$cid||!$eid||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))throw new RuntimeException('Employee, campaign and a valid assignment date are required.');$conn->begin_transaction();try{$u=$conn->prepare('UPDATE employee_campaign_assignments SET is_active=0,assigned_to=? WHERE employee_id=? AND is_active=1');$u->bind_param('si',$from,$eid);$u->execute();$s=$conn->prepare("INSERT INTO employee_campaign_assignments(employee_id,campaign_id,assigned_from,is_active) SELECT ?,?,?,1 FROM employees e JOIN performance_campaigns c ON c.id=? WHERE e.id=? AND e.status='Active' AND e.is_active=1 AND c.is_active=1");$s->bind_param('iisii',$eid,$cid,$from,$cid,$eid);$s->execute();if($s->affected_rows!==1)throw new RuntimeException('Employee or campaign is not active.');$conn->commit();$msg='Employee campaign assigned successfully.';}catch(Throwable $e){$conn->rollback();throw $e;}}
  elseif($action==='unassign'){$assignmentId=(int)($_POST['assignment_id']??0);if(!$assignmentId)throw new RuntimeException('Invalid campaign assignment.');$s=$conn->prepare('UPDATE employee_campaign_assignments SET is_active=0,assigned_to=CURDATE() WHERE id=? AND is_active=1');$s->bind_param('i',$assignmentId);$s->execute();if($s->affected_rows!==1)throw new RuntimeException('Assignment is already removed or was not found.');$msg='Employee removed from the active campaign. Performance history is محفوظ.';}
  elseif($action==='update_kpi'){$kpiId=(int)($_POST['kpi_id']??0);$name=trim($_POST['kpi_name']??'');$weight=(float)($_POST['weight']??0);if(!$kpiId||$name===''||$weight<=0)throw new RuntimeException('KPI name and positive marks are required.');$q=$conn->prepare('SELECT campaign_id FROM campaign_kpis WHERE id=?');$q->bind_param('i',$kpiId);$q->execute();$found=$q->get_result()->fetch_assoc();if(!$found)throw new RuntimeException('KPI was not found.');$cid=(int)$found['campaign_id'];$sum=$conn->prepare('SELECT COALESCE(SUM(weight),0) total FROM campaign_kpis WHERE campaign_id=? AND id<>?');$sum->bind_param('ii',$cid,$kpiId);$sum->execute();$otherWeight=(float)$sum->get_result()->fetch_assoc()['total'];if($otherWeight+$weight>100.001)throw new RuntimeException('Total KPI marks cannot exceed 100.');$code=strtolower(trim(preg_replace('/[^a-zA-Z0-9]+/','_',$name)??'','_'));$duplicate=$conn->prepare('SELECT id FROM campaign_kpis WHERE campaign_id=? AND kpi_code=? AND id<>?');$duplicate->bind_param('isi',$cid,$code,$kpiId);$duplicate->execute();if($duplicate->get_result()->fetch_assoc())$code.='_'.$kpiId;$s=$conn->prepare('UPDATE campaign_kpis SET kpi_name=?,kpi_code=?,weight=? WHERE id=?');$s->bind_param('ssdi',$name,$code,$weight,$kpiId);$s->execute();$msg='KPI name and marks updated successfully. Existing performance history remains safe.';}
 }catch(Throwable $e){$msg=$e->getMessage();$type='danger';}
}
$campaigns=$conn->query("SELECT c.*,COALESCE(SUM(k.weight),0) total_weight,COUNT(k.id) kpi_count FROM performance_campaigns c LEFT JOIN campaign_kpis k ON k.campaign_id=c.id GROUP BY c.id ORDER BY c.name")->fetch_all(MYSQLI_ASSOC);
$employees=$conn->query("SELECT id,employee_id,full_name,department FROM employees WHERE status='Active' AND is_active=1 ORDER BY full_name")->fetch_all(MYSQLI_ASSOC);
$kpis=$conn->query("SELECT k.*,c.name campaign_name FROM campaign_kpis k JOIN performance_campaigns c ON c.id=k.campaign_id ORDER BY c.name,k.display_order,k.id")->fetch_all(MYSQLI_ASSOC);
$assignments=$conn->query("SELECT a.*,e.employee_id employee_code,e.full_name,c.name campaign_name FROM employee_campaign_assignments a JOIN employees e ON e.id=a.employee_id JOIN performance_campaigns c ON c.id=a.campaign_id WHERE a.is_active=1 ORDER BY e.full_name")->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Campaign KPI Setup</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><style>body{background:#f4f7fb}.card{border:0;border-radius:16px;box-shadow:0 7px 22px #16345c12}.top{background:#173a70;color:#fff}.table th{font-size:12px;text-transform:uppercase}</style></head><body><header class="top p-4"><div class="d-flex justify-content-between"><div><h2><i class="fa fa-layer-group me-2"></i>Campaign & KPI Setup</h2><div class="opacity-75">Manage multiple campaigns and their KPI weights</div></div><div><a href="campaign_performance.php" class="btn btn-success me-2">Bulk Performance Upload</a><a href="psm_kpi.php" class="btn btn-light">Back</a></div></div></header><main class="container-fluid p-4"><?php if($msg):?><div class="alert alert-<?=$type?> alert-dismissible fade show" role="alert"><?=htmlspecialchars($msg)?><button type="button" class="btn-close" onclick="this.parentElement.remove()" aria-label="Close"></button></div><?php endif;?>
<div class="row g-4"><div class="col-lg-4"><div class="card p-4"><h4>Add Campaign</h4><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(ems_csrf_token())?>"><input type="hidden" name="action" value="campaign"><label class="form-label">Campaign Name</label><input name="name" class="form-control mb-3" required><label class="form-label">Description</label><textarea name="description" class="form-control mb-3"></textarea><button class="btn btn-primary">Add Campaign</button></form></div></div>
<div class="col-lg-4"><div class="card p-4"><h4>Add Campaign KPI</h4><div class="alert alert-info py-2 small"><strong>Example:</strong> KPI Name = Call Quality, Marks = 30.<br>Sab KPIs ke total marks 100 hone chahiye.</div><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(ems_csrf_token())?>"><input type="hidden" name="action" value="kpi"><label class="form-label fw-bold">1. Campaign select karein</label><select name="campaign_id" class="form-select mb-3" required><option value="">Select Campaign</option><?php foreach($campaigns as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['name'])?> — Used <?=$c['total_weight']?>%, Remaining <?=max(0,100-(float)$c['total_weight'])?>%</option><?php endforeach;?></select><label class="form-label fw-bold">2. KPI ka naam</label><input name="kpi_name" class="form-control mb-1" placeholder="e.g. Call Quality" required><small class="text-muted d-block mb-3">KPI Code system automatically bana dega.</small><label class="form-label fw-bold">3. KPI ke maximum marks</label><div class="input-group mb-1"><input type="number" step="0.01" min="0.01" max="100" name="weight" class="form-control" placeholder="e.g. 30" required><span class="input-group-text">Marks / %</span></div><small class="text-muted d-block mb-3">Call Quality 30, Attendance 15, Login 5 — total 100.</small><button class="btn btn-primary"><i class="fa fa-plus me-1"></i> Add KPI</button></form></div></div>
<div class="col-lg-4"><div class="card p-4"><h4>Assign Employee Campaign</h4><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(ems_csrf_token())?>"><input type="hidden" name="action" value="assign"><select name="employee_id" class="form-select mb-3" required><option value="">Select Employee</option><?php foreach($employees as $e):?><option value="<?=$e['id']?>"><?=htmlspecialchars($e['employee_id'].' - '.$e['full_name'])?></option><?php endforeach;?></select><select name="campaign_id" class="form-select mb-3" required><option value="">Select Campaign</option><?php foreach($campaigns as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select><input type="date" name="assigned_from" value="<?=date('Y-m-d')?>" class="form-control mb-3"><button class="btn btn-primary">Assign Campaign</button></form></div></div></div>
<div class="row g-4 mt-1"><div class="col-lg-7"><div class="card overflow-hidden"><div class="p-3"><h4>Campaign KPIs</h4><label for="kpiCampaignFilter" class="form-label small text-muted mb-1">Campaign select karein</label><select id="kpiCampaignFilter" class="form-select form-select-sm" style="max-width:320px" onchange="filterCampaignKpis(this.value)"><option value="">All Campaigns</option><?php foreach($campaigns as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select><small class="text-muted d-block mt-2">Name ya marks change karke Save click karein.</small></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Campaign</th><th>KPI Name</th><th>Marks</th><th>Action</th></tr></thead><tbody><?php foreach($kpis as $k):?><tr class="campaign-kpi-row" data-campaign-id="<?=$k['campaign_id']?>"><form method="post"><td><?=htmlspecialchars($k['campaign_name'])?><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(ems_csrf_token())?>"><input type="hidden" name="action" value="update_kpi"><input type="hidden" name="kpi_id" value="<?=$k['id']?>"></td><td><input name="kpi_name" value="<?=htmlspecialchars($k['kpi_name'])?>" class="form-control form-control-sm" required></td><td><div class="input-group input-group-sm" style="min-width:105px"><input type="number" step="0.01" min="0.01" max="100" name="weight" value="<?=$k['weight']?>" class="form-control" required><span class="input-group-text">%</span></div></td><td><button class="btn btn-sm btn-primary"><i class="fa fa-floppy-disk me-1"></i> Save</button></td></form></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-lg-5"><div class="card overflow-hidden"><div class="p-3"><h4>Active Employee Campaigns</h4></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Employee</th><th>Campaign</th><th>From</th><th>Action</th></tr></thead><tbody><?php foreach($assignments as $a):?><tr><td><?=htmlspecialchars($a['employee_code'].' - '.$a['full_name'])?></td><td><?=htmlspecialchars($a['campaign_name'])?></td><td><?=$a['assigned_from']?></td><td><form method="post" onsubmit="return confirm('Remove this employee from the active campaign? Performance history will remain safe.');"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(ems_csrf_token())?>"><input type="hidden" name="action" value="unassign"><input type="hidden" name="assignment_id" value="<?=$a['id']?>"><button class="btn btn-sm btn-outline-danger"><i class="fa fa-user-minus me-1"></i> Remove</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div><script>function filterCampaignKpis(campaignId){document.querySelectorAll('.campaign-kpi-row').forEach(function(row){row.style.display=!campaignId||row.dataset.campaignId===campaignId?'':'none';});}</script></main></body></html>
